arguments.command:
# The binary has dynamic symbols even if stripped - try dynsym
objdump -T /tmp/symbols/libmonosgen-2.0.so 2>/dev/null | wc -l
# Also try using the dynamic symbol table to resolve addresses
for addr in 0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04; do
  result=$(objdump -T /tmp/symbols/libmonosgen-2.0.so 2>/dev/null | awk -v a="$addr" '
    BEGIN { target = strtonum(a); best_name = ""; best_addr = 0; best_offset = 99999999 }
    /^[0-9a-f]/ {
      sym_addr = strtonum("0x" $1)
      if (sym_addr <= target && (target - sym_addr) < best_offset) {
        best_offset = target - sym_addr
        best_addr = sym_addr
        best_name = $NF
      }
    }
    END { if (best_name != "") printf "%s+0x%x\n", best_name, best_offset; else print "???" }
  ')
  echo "$addr -> $result"
done

